//! Every function the crate declares (for the enabled feature set) resolves in the installed AOCL-LibFlame / BLIS (taking the
//! address forces the link). The list is generated by build.rs from the bindings actually generated, so it follows the features.
//! MEASURED on AOCL 6.0.68 Windows (LP64 and ILP64; Linux unmeasured): the 150 names left out by default (`LAPACKE_*x`/`xx` and
//! their `_work`, Fortran `*x_`/`clagge_`-type; feature `header-only-unexported`) are exported by NO installed library, so
//! enabling that feature makes this test fail to link on Windows by design; `lsame_` is exported by BLIS (feature `blis`).
#![allow(warnings)]

#[test]
fn declared_symbols_link() {
    let addrs: Vec<usize> = include!(concat!(env!("OUT_DIR"), "/link_all_list.rs"));
    let expected = 3697 + if cfg!(feature = "blis") { 1 } else { 0 };
    if !cfg!(feature = "header-only-unexported") {
        assert_eq!(addrs.len(), expected);
    }
    assert!(addrs.iter().all(|a| *a != 0));
}
